package spireledger;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class StatsIndexCheck {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static JsonObject parse(String json){return new JsonParser().parse(json).getAsJsonObject();}
 static JsonObject nativeRun(String id,boolean victory){JsonObject o=parse("{\"character_chosen\":\"IRONCLAD\",\"ascension_level\":0,\"timestamp\":100,\"seed_played\":\"same-seed\",\"floor_reached\":57,\"master_deck\":[\"Bash\",\"Bash+1\"],\"path_per_floor\":[\"M\",null,\"M\",null,\"M\",null,\"B\"],\"damage_taken\":[{\"enemies\":\"The Heart\",\"floor\":56,\"damage\":12}],\"playtime\":120}");o.addProperty("play_id",id);o.addProperty("victory",victory);if(!victory)o.addProperty("killed_by","The Heart");return o;}
 static JsonObject state(int act,int floor){JsonObject s=parse("{\"class\":\"IRONCLAD\",\"ascension\":20,\"deck\":[{\"id\":\"Bash\",\"instance_id\":\"a\",\"upgrades\":0}],\"hp\":20,\"max_hp\":80,\"gold\":1,\"potions\":[],\"relics\":[]}");s.addProperty("act",act);s.addProperty("floor",floor);return s;}
 static void add(JsonArray records,JsonObject e,String branch,int seq){e.addProperty("branch_id",branch);e.addProperty("seq",seq);e.addProperty("time_ms",100000);records.add(e);}
 static void decision(JsonArray records,String id,String branch,int seq,int act,String kind){JsonObject d=Recorder.object("decision");d.addProperty("decision_id",id);d.addProperty("source","COMBAT_REWARD");d.addProperty("action_source","unknown");d.addProperty("candidate_id",kind.equals("card")?"card:0":kind);d.add("before",state(act,act*10));d.add("candidates",parse("{\"items\":[{\"candidate_id\":\"card:0\",\"type\":\"card\",\"card\":{\"id\":\"Bash\",\"upgrades\":0}},{\"candidate_id\":\"card:1\",\"type\":\"card\",\"card\":{\"id\":\"Bash\",\"upgrades\":1}},{\"candidate_id\":\"skip\",\"type\":\"skip\"},{\"candidate_id\":\"bowl\",\"type\":\"bowl\"}]}").get("items"));add(records,d,branch,seq);JsonObject result=Recorder.object("result");result.addProperty("decision_id",id);result.addProperty("status","confirmed");result.add("after",state(act,act*10));add(records,result,branch,seq+1);}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]);Files.createDirectories(root.resolve("IRONCLAD"));JsonObject first=nativeRun("one",true),second=nativeRun("two",false);byte[] original=first.toString().getBytes(StandardCharsets.UTF_8);Files.write(root.resolve("IRONCLAD/first.run"),original);Files.write(root.resolve("IRONCLAD/copy.run"),original);Files.write(root.resolve("IRONCLAD/second.run"),second.toString().getBytes(StandardCharsets.UTF_8));
  Files.write(root.resolve("IRONCLAD/unrecognized.run"),"{}".getBytes(StandardCharsets.UTF_8));
  StatsIndex.Index index=StatsIndex.scan(root,new HistoryIndex.Index(),null);check(index.errors.size()==1,"unrecognized native format excluded");check(index.nativeRuns.size()==2&&index.nativeDuplicates==1,"play ID dedup, same seed separate");StatsIndex.Filter f=new StatsIndex.Filter();List<StatsIndex.Run> runs=StatsIndex.filter(index,f,100000);Map<String,StatsIndex.Metric> m=StatsIndex.metrics(runs,f);check(m.get("win").numerator==1&&m.get("win").denominator==2,"heart rate denominator");for(StatsIndex.Run r:index.nativeRuns)check(r.actor.equals("unknown"),"unlinked native runs carry no actor");check(runs.size()==2,"default filter counts unlinked native runs");StatsIndex.Filter human=new StatsIndex.Filter();human.source="human";check(StatsIndex.filter(index,human,100000).isEmpty(),"an actor filter would hide every unlinked native run, so the UI must not offer one");check(m.get("holding:Bash").denominator==2,"same-name held once per run");check(m.get("damage:The Heart").value==12,"explicit damage");check(m.get("death_count:The Heart").numerator==1,"explicit native death frequency");check(m.get("coverage:potions").numerator==0,"missing potions not zero use");check(m.get("time").denominator==2,"time eligible only");
  JsonObject nullFields=nativeRun("null-fields",true);nullFields.add("potions_floor_usage",JsonNull.INSTANCE);nullFields.add("items_purchased",JsonNull.INSTANCE);nullFields.add("neow_bonus",JsonNull.INSTANCE);StatsIndex.Run nullRun=StatsIndex.nativeRun(nullFields,"");check(!nullRun.available.contains("potions")&&!nullRun.available.contains("purchases")&&!nullRun.available.contains("neow"),"null fields are missing, not zero");JsonObject missing=parse("{\"character_chosen\":\"DEFECT\",\"seed_played\":\"same-seed\"}");StatsIndex.Run unknown=StatsIndex.nativeRun(missing,"missing");check(unknown.outcome.equals("incomplete")&&StatsIndex.win(unknown,true)==null,"missing result not death");JsonObject ambiguous=nativeRun("ambiguous",true);ambiguous.remove("damage_taken");check(StatsIndex.win(StatsIndex.nativeRun(ambiguous,""),true)==null,"heart detail unavailable not failure");JsonObject abandon=nativeRun("abandon",false);abandon.addProperty("abandoned",true);StatsIndex.Run abandoned=StatsIndex.nativeRun(abandon,"");index.nativeRuns.add(abandoned);check(StatsIndex.filter(index,f,100000).size()==2,"abandon default excluded");f.includeAbandon=true;check(StatsIndex.filter(index,f,100000).size()==3,"abandon optional");
  // Vanilla .run with neither victory nor killed_by is abandoned (proposed default); incomplete runs never enter formal stats.
  JsonObject quit=nativeRun("quit",false);quit.remove("killed_by");StatsIndex.Run quitRun=StatsIndex.nativeRun(quit,"");check(quitRun.outcome.equals("abandon")&&Boolean.FALSE.equals(StatsIndex.win(quitRun,true)),"vanilla run without killed_by is abandoned, not incomplete");index.nativeRuns.add(quitRun);index.nativeRuns.add(StatsIndex.nativeRun(missing,"missing-2"));
  check(StatsIndex.filter(index,f,100000).size()==4,"abandon on: both abandoned runs counted, incomplete excluded");f.includeAbandon=false;check(StatsIndex.filter(index,f,100000).size()==2,"abandon off: abandoned and incomplete both excluded");f.includeAbandon=true;
  JsonObject doc=parse("{\"schema\":\"spire-ledger-v1\",\"metadata\":{\"run_id\":\"notes-one\",\"seed\":\"same-seed\"},\"records\":[]}");JsonArray records=doc.getAsJsonArray("records");decision(records,"first","a",1,1,"card");JsonObject point=Recorder.object("checkpoint");point.addProperty("checkpoint_id","cp");add(records,point,"a",3);decision(records,"discarded-attempt","a",4,3,"bowl");JsonObject load=Recorder.object("load");load.addProperty("parent_checkpoint_id","cp");load.addProperty("parent_status","local_checkpoint_found");add(records,load,"b",6);decision(records,"final","b",7,3,"skip");JsonObject end=Recorder.object("ending");end.addProperty("outcome","death");end.add("state",state(3,50));add(records,end,"b",9);StatsIndex.Run notes=StatsIndex.notesRun(doc,HistoryIndex.summarize(doc,false));check(notes.values.get("pick:1:Bash")[1]==1,"duplicate candidates one appearance");check(notes.values.get("pick:1:Bash")[0]==1,"picked once");check(notes.values.get("skip:3")[0]==1&&notes.values.get("bowl:3")[0]==0,"third-act skip and ancestry");check(notes.pathExcluded==0,"known checkpoint ancestry");load.addProperty("parent_status","unknown");StatsIndex.Run orphan=StatsIndex.notesRun(doc,HistoryIndex.summarize(doc,false));check(!orphan.values.containsKey("pick:1:Bash")&&orphan.pathExcluded==1,"unknown ancestor not stitched");
  JsonArray turns=new JsonArray();JsonObject early=Recorder.object("floor");add(turns,early,"old",1);JsonObject turnPoint=Recorder.object("turn_snapshot");turnPoint.addProperty("snapshot_id","turn-two");add(turns,turnPoint,"old",3);JsonObject discarded=Recorder.object("floor");add(turns,discarded,"old",4);JsonObject rollback=Recorder.object("turn_rollback");rollback.addProperty("snapshot_id","turn-two");rollback.addProperty("parent_branch_id","old");add(turns,rollback,"new",6);JsonObject child=Recorder.object("floor");add(turns,child,"new",7);StatsIndex.Run turnRun=new StatsIndex.Run();List<JsonObject> path=StatsIndex.finalPath(turns,turnRun);check(path.contains(early)&&path.contains(turnPoint)&&path.contains(child)&&!path.contains(discarded)&&turnRun.pathExcluded==0,"turn rollback preserves earlier floors and excludes abandoned attempt");rollback.addProperty("parent_branch_id","wrong");turnRun=new StatsIndex.Run();check(!StatsIndex.finalPath(turns,turnRun).contains(early)&&turnRun.pathExcluded==1,"mismatched turn ancestry excluded");rollback.addProperty("parent_branch_id","old");rollback.addProperty("snapshot_id","missing");turnRun=new StatsIndex.Run();check(!StatsIndex.finalPath(turns,turnRun).contains(early)&&turnRun.pathExcluded==1,"missing turn ancestry excluded");
  notes.session="practice";index.notesRuns.add(notes);f.scope="notes";check(StatsIndex.filter(index,f,100000).isEmpty(),"practice defaults excluded");notes.session="";notes.fixture=true;check(StatsIndex.filter(index,f,100000).isEmpty(),"fixture excluded");notes.fixture=false;notes.conflict=true;check(StatsIndex.filter(index,f,100000).isEmpty(),"conflict excluded");notes.conflict=false;check(StatsIndex.filter(index,f,100000).size()==1,"ended notes run counted");notes.outcome="incomplete";check(StatsIndex.filter(index,f,100000).isEmpty(),"notes run without ending excluded");check(Arrays.equals(original,Files.readAllBytes(root.resolve("IRONCLAD/first.run"))),"read only native files");
  System.out.println("StatsIndexCheck PASS: precise denominators, seed/ID, duplicate cards/candidates, missing/abandon, path, practice and read only");
 }
}
